document.addEventListener("doofinder.cart.add", async event => {

	const {item_id, amount} = event.detail

	if (!pmwDataLayer.products[item_id]) {
		await pmw.getProductsFromBackend([item_id])
	}

	if (!pmwDataLayer.products[item_id]) {
		console.log("Product not found in dataLayer or server. Exiting...")
		return
	}

	let product = pmw.getProductDetailsFormattedForEvent(item_id, amount)

	if (!product) {
		pmw.console.error("Product not found")
		return
	}

	// Trigger "pmw:add-to-cart" event using jQuery
	pmw.bus.emit("pmw:add-to-cart", product)
})
